 function render(){const items=all();$('#local-count').textContent=state.native.length+state.legacy.length;$('#drive-count').textContent=state.status.drive.connected?state.drivePage.length:'—';const recent=UI.recent(items);$('#recommended').innerHTML=recent.length?recent.slice(0,8).map(card).join(''):state.driveLoading?loadingMarkup():empty('Новые записи появятся здесь','Добавь файлы или подключи свою библиотеку.');const history=state.history.map(get).filter(Boolean);const continuing=history.filter(t=>!state.completed.includes(t.id)&&position(t)>0);$('#continue-list').innerHTML=continuing.length?continuing.slice(0,4).map(t=>UI.continueCard(t,position(t),art)).join(''):empty('Начни с любимой записи','Твоя текущая глава и позиция появятся здесь после прослушивания.');list('#recent',history.slice(0,6));renderLibrary();list('#playlist-list',state.playlist.map(get).filter(Boolean),{playlist:true});const missing=state.playlist.filter(id=>!get(id)).length;$('#playlist-summary').textContent=missing?'Не отображаются '+missing+' записей, недоступных в текущих хранилищах. Сохранённый плейлист не удалён.':'Песни хранятся на ПК или Google Диске.';list('#queue-list',state.queue.map(get).filter(Boolean),{queue:true});folderList('#drive-list',state.drivePage.filter(t=>t.kind===$('#drive-kind').value),$('#drive-query').value);$('#drive-summary').textContent=state.status.drive.connected?'Страница '+(state.driveIndex+1)+' · '+state.drivePage.length+' файлов':'Подключи аккаунт';$('#drive-next').disabled=!state.driveNext;$('#drive-first').disabled=state.driveIndex===0;$('#shuffle').setAttribute('aria-pressed',String(state.shuffle));$('#repeat').value=state.repeat;updatePlayer()}
 function updatePlayer(){const current=state.current;$$('[data-track]').forEach(element=>element.classList.toggle('current',element.dataset.track===current?.id));$$('[data-play]').forEach(button=>{if(button.classList.contains('art'))return;button.innerHTML=icon(button.dataset.play===current?.id&&!a.paused?'pause':'play',18)+(button.classList.contains('primary')?' '+(button.dataset.play===current?.id&&!a.paused?'Пауза':position(get(button.dataset.play)||{})?'Продолжить':'Слушать'):'')});$('#play').innerHTML=icon(a.paused?'play':'pause');if(current){$('#now-title').textContent=current.title;$('#now-artist').textContent=current.artist+' · '+(current.storage==='drive'?'Google Диск':'ПК');$('#now-art').innerHTML=art(current,true)}else{$('#now-title').textContent='Выбери песню';$('#now-artist').textContent='ПК и Google Диск';$('#now-art').innerHTML=icon('music',24)}}
 function show(view){state.view=view;$$('.view').forEach(el=>el.classList.toggle('active-view',el.id===view));$$('.sidebar [data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));window.scrollTo(0,0);render();if(view==='drive'&&state.status.drive.connected&&!state.drivePage.length)loadDrive()}
 async function refreshStatus(){try{state.status=await call('status');$('#app-version').textContent='MeguBoom '+state.status.version+' · Personal Cloud Player';$('#local-path').textContent='Загрузки: '+state.status.libraryDirectory;renderCloudStatus()}catch{notice('Открой установленное приложение Windows для подключения Диска и работы с папками.')}}
 function renderCloudStatus(){const d=state.status.drive;if(d.connected&&!state.driveLoaded)state.driveLoading=true;if(!d.connected)$('#collection-shortcuts').innerHTML='';$('#connection-pill').textContent=d.connected?'Google Диск подключён':'Локальная библиотека';$('#drive-state').textContent=d.connecting?'Ожидаю подтверждение в браузере Google…':d.connected?'Аккаунт подключён. Можно искать и слушать файлы без скачивания всего Диска.':d.configured?'OAuth настроен. Нажми «Подключить Google».':'Выбери OAuth JSON для приложения Desktop app, затем подключи аккаунт.';$('#connect-drive').disabled=!d.configured||d.connecting;$('#configure-drive').disabled=d.connecting;$('#configure-drive').classList.toggle('hidden',d.connected);$('#drive-connect-panel h2').textContent=d.connected?'Google Диск подключён':'Подключи свою облачную библиотеку';$('#connect-drive').classList.toggle('hidden',d.connected);$('#cancel-drive').classList.toggle('hidden',!d.connecting);$('#disconnect-drive').classList.toggle('hidden',!d.connected);if(!d.connected){state.cloud=[];state.drivePage=[];state.driveNext=null}render()}
 async function refreshLocal(){state.native=await call('listLocal');render()}
 async function importFiles(folder=false){if(!window.personal){$('#legacy-import').click();return}const result=await call('importLocal',{folder});await refreshLocal();notice('Добавлено: '+result.added.length+' · повторов: '+(result.duplicates||0)+' · пропущено: '+result.skipped);show('library')}
 async function play(id){const t=get(id);if(!t||!canPlay(t))throw Error('Аудиофайл недоступен');if(state.current?.id===id&&a.src){if(a.paused)await resumePlayback();else a.pause();return}const sequence=++state.playSequence;a.pause();await beforePlayback(t);if(sequence!==state.playSequence)return;notice('Открываю «'+t.title+'»…');let url=t.legacyURL;if(!url)url=(await call('playback',{id:t.id,storage:t.storage,fileId:t.fileId})).url;if(sequence!==state.playSequence)return;const parsed=new URL(url);if(parsed.protocol!=='blob:'&&(parsed.protocol!=='http:'||parsed.hostname!=='127.0.0.1'))throw Error('В библиотеке воспроизводятся только файлы ПК и Google Диска');state.current=t;currentPlaybackScope=progressScope;a.src=url;await a.play();if(sequence!==state.playSequence)return;state.history=[id,...state.history.filter(x=>x!==id)].slice(0,50);save();notice('');render()}
 async function step(direction,ended=false){const ids=state.queue.filter(id=>get(id)&&canPlay(get(id))),id=queueUtils.nextId({ids,currentId:state.current?.id,direction,ended,repeat:state.repeat});if(id){if(id===state.current?.id){a.currentTime=0;await a.play()}else await play(id)}else if(ended){a.pause();notice('Очередь завершена')}}
 function migrateDriveIdentities(files){const aliases=new Map(files.filter(t=>t.legacyId&&t.legacyId!==t.id).map(t=>[t.legacyId,t.id]));for(const key of ['favorites','playlist','history','completed','queue'])state[key]=[...new Set(state[key].map(id=>aliases.get(id)||id))];state.cached=state.cached.filter(t=>!aliases.has(t.id));for(const [oldId,id]of aliases){const previous=localStorage.getItem('meguboom-progress-'+oldId);if(previous!==null&&localStorage.getItem('meguboom-progress-'+id)===null)localStorage.setItem('meguboom-progress-'+id,previous);if(!state.durations[id]&&state.durations[oldId])state.durations[id]=state.durations[oldId]}localStorage.setItem('meguboom-durations',JSON.stringify(state.durations));}
 async function loadDrive(reset=true){if(!state.status.drive.connected){notice('Сначала подключи Google Диск');return}if(reset){state.driveIndex=0;state.driveTokens=[null]}const sequence=++state.driveSequence;state.driveLoading=true;state.driveError='';render();notice('Загружаю папки и книги с Google Диска…');try{const result=await call('listDrive',{query:$('#drive-query').value,folder:$('#drive-folder').value,kind:$('#drive-kind').value,pageToken:state.driveTokens[state.driveIndex]});if(sequence!==state.driveSequence)return;migrateDriveIdentities(result.files);state.drivePage=result.files;state.driveLoaded=true;state.driveNext=result.nextPageToken;if($('#drive-folder').value.trim()&&!$('#drive-query').value.trim()){state.cloud=result.files;state.cached=[]}else state.cloud=personalModel.library([...state.cloud,...result.files]).slice(-2000);save();render();notice('');seedProgress(result.files).then(()=>syncProgress()).catch(error=>{progressState={...progressState,state:'error',error:error.message};renderProgressStatus()})}catch(error){if(sequence===state.driveSequence){state.driveLoaded=true;state.driveError=error.message;notice(error.message)}}finally{if(sequence===state.driveSequence){state.driveLoading=false;render()}}}
